// Score Agent — app icons served from embedded base64.
// The GitHub snapshot push is UTF-8 text only, so the PNG icons live here
// as base64 text and are served as image/png: /api/icons?s=192|512|m512|logo
// HOME-SCREEN icons (192/512/m512): the elite mark with white SA under it
// (Brandon 2026-11-22, approved preview: guy bigger, SA wide + 3D pop).
// "logo" = the PLAIN mark with NO SA — every in-app use points here
// (Brandon: "Keep the icon on actual app the same tho no sa").
// 512/192 at 92% of canvas, maskable at 72% so nothing is cut off in the
// splash circle.
const ICONS = {"192": "", "512": "", "m512": "", "logo": ""};
module.exports = (req, res) => {
  const s = (req.query && req.query.s) || "192";
  const body = ICONS[s] || ICONS["192"];
  res.setHeader("Content-Type", "image/png");
  res.setHeader("Cache-Control", "public, max-age=31536000, immutable");
  res.status(200).send(Buffer.from(body, "base64"));
};
